537	    private Xzn53Status mapToShipmentStatus(String statusText) {
538	        return switch (statusText) {
539	            case "배송완료" -> Xzn53Status.DELIVERED;
540	            case "배송출발" -> Xzn53Status.OUT_FOR_DELIVERY;
541	            default -> Xzn53Status.IN_TRANSIT;
542	        };
543	    }
