429	            log.info("운송장 정보 업데이트 완료: shipmentId={}", shipmentId);
430	
431	        } catch (Xzn53Exception e) {
432	            throw e;
433	        } catch (Exception e) {
434	            log.error("운송장 정보 업데이트 실패: shipmentId={}, error={}", shipmentId, e.getMessage(), e);
435	            throw new Xzn53Exception(
436	                    Xzn53ErrorCode.SHIPMENT_NOT_FOUND,
437	                    "운송장 정보 업데이트 중 오류 발생: " + e.getMessage(),
438	                    e
439	            );
440	        }
441	    }
