562	                orderBid.updateStatus(com.fream.back.domain.m99.entity.Xkh73Status.COMPLETED);
563	            }
564	
565	
566	            Xzt63 saleBid = saleBidQueryService.findByOrderId(orderId);
567	            if (saleBid != null && saleBid.getStatus() == Xkh73Status.MATCHED) {
568	                log.debug("Xzt63 상태 COMPLETED로 변경: saleBidId={}", saleBid.getId());
569	                saleBid.updateStatus(Xkh73Status.COMPLETED);
570	            }
571	
572	            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);
573	
574	        } catch (Exception e) {
575	            log.error("입찰 상태 변경 실패: orderId={}, error={}", orderId, e.getMessage(), e);
576	
577	        }
