589	    @Transactional
590	    public Xzn53Status updateAndCheckShipmentStatus(Long shipmentId, String courier, String trackingNumber) throws Exception {
591	        log.info("단일 송장 상태 즉시 조회 및 업데이트: shipmentId={}, courier={}, trackingNumber={}",
592	                shipmentId, courier, trackingNumber);
593	
594	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
595	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
596	            throw new Xzn53Exception(Xzn53ErrorCode.TRACKING_INFO_REQUIRED);
597	        }
598	
599	        try {
600	
601	            Xfr60 shipment = orderShipmentRepository.findById(shipmentId)
602	                    .orElseThrow(() -> new Xzn53Exception(
603	                            Xzn53ErrorCode.SHIPMENT_NOT_FOUND,
604	                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
605	                    ));
606	
607	            log.debug("배송 정보 조회 완료: shipmentId={}, 현재상태={}",
608	                    shipment.getId(), shipment.getStatus());
609	
610	
611	            shipment.updateTrackingInfo(courier, trackingNumber);
612	            log.debug("송장 정보 업데이트 완료: courier={}, trackingNumber={}", courier, trackingNumber);
613	
614	
615	            String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
616	            Xzn53Status newStatus = mapToShipmentStatus(currentStatus);
617	
618	            log.info("배송 상태 조회 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
619	
620	
621	            if (newStatus == Xzn53Status.DELIVERED) {
622	                log.info("배송 완료 처리: shipmentId={}", shipmentId);
623	
624	                shipment.updateStatus(Xzn53Status.DELIVERED);
625	
626	
627	                completeOrder(shipment.getOrder().getId());
628	
629	            } else if (newStatus == Xzn53Status.OUT_FOR_DELIVERY) {
630	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
631	                shipment.updateStatus(Xzn53Status.OUT_FOR_DELIVERY);
632	
633	            } else {
634	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
635	                shipment.updateStatus(Xzn53Status.IN_TRANSIT);
636	            }
637	
638	
639	            log.info("송장 상태 확인 완료: shipmentId={}, finalStatus={}",
640	                    shipmentId, shipment.getStatus());
641	            return shipment.getStatus();
642	
643	        } catch (Xzn53Exception e) {
644	            throw e;
645	        } catch (Exception e) {
646	            log.error("송장 상태 확인 중 오류 발생: shipmentId={}, error={}",
647	                    shipmentId, e.getMessage(), e);
648	            throw new Xzn53Exception(
649	                    Xzn53ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
650	                    "배송 상태 조회 중 오류 발생: " + e.getMessage(),
651	                    e
652	            );
653	        }
654	    }
655	}

